INSERT INTO "pages" VALUES ('fddf5fb6-7b12-4e4f-a30d-5104e041cc24', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 0, NULL, '{"title": "火箭发动机原理", "points": ["副标题：探索宇宙的动力之源", "汇报人：[您的姓名]"]}', '{"text": "页面文字：\n# 火箭发动机原理\n## 探索宇宙的动力之源\n汇报人：[您的姓名]", "generated_at": "2026-04-06T09:31:44.573808", "extra_fields": {"视觉元素": "背景使用深色星空或简洁的几何图形，营造科技感。", "视觉焦点": "中心标题“火箭发动机原理”。", "排版布局": "居中对齐，极简设计，不添加多余装饰。", "演讲者备注": "大家好，今天我们将深入探讨驱动人类走向深空的动力之源——火箭发动机的工作原理。"}}', '25baf07b-ed71-48c9-8515-d4d7158ac7c5/pages/fddf5fb6-7b12-4e4f-a30d-5104e041cc24_v1.png', 'COMPLETED', '2026-04-06 09:31:28.461607', '2026-04-06 09:36:25.362390', '25baf07b-ed71-48c9-8515-d4d7158ac7c5/pages/fddf5fb6-7b12-4e4f-a30d-5104e041cc24_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('79b9c781-a72f-4bf8-a116-e43a447d5a4c', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 1, '第 1 部分：火箭发动机概述', '{"title": "什么是火箭发动机", "points": ["定义：一种自带推进剂，不依赖外界空气工作的动力装置", "基本功能：将化学能或其他形式的能量转化为动能", "核心特征：能在真空环境下产生推力"]}', '{"text": "页面文字：\n### 什么是火箭发动机\n*   **核心定义**：自带推进剂，不依赖外界空气工作的动力装置\n*   **基本功能**：将化学能或其他形式能量高效转化为动能\n*   **核心特征**：唯一能在真空环境下产生推力的动力系统", "generated_at": "2026-04-06T09:31:45.619849", "extra_fields": {"视觉元素": "火箭在真空中喷火航行的示意图。", "视觉焦点": "强调“自带推进剂”和“真空工作”的特性。", "排版布局": "左文右图，要点采用图标列表形式。", "演讲者备注": "火箭发动机与喷气式飞机发动机最大的不同在于它不呼吸空气，这让它成为了征服宇宙的唯一手段。"}}', '25baf07b-ed71-48c9-8515-d4d7158ac7c5/pages/79b9c781-a72f-4bf8-a116-e43a447d5a4c_v1.png', 'COMPLETED', '2026-04-06 09:31:28.461607', '2026-04-06 09:36:42.148616', '25baf07b-ed71-48c9-8515-d4d7158ac7c5/pages/79b9c781-a72f-4bf8-a116-e43a447d5a4c_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('fa2c3f73-20f5-4a6b-80df-0c47cc3c6d75', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 2, '第 1 部分：火箭发动机概述', '{"title": "火箭发动机的历史演变", "points": ["古代中国的火药箭", "近代先驱：齐奥尔科夫斯基与戈达德", "现代航天：从V-2火箭到重型猎鹰"]}', '{"text": "页面文字：\n### 火箭发动机的历史演变\n*   **古代中国**：南宋时期的火药箭是火箭技术的雏形\n*   **近代先驱**：齐奥尔科夫斯基与戈达德奠定了理论与实验基础\n*   **现代航天**：从V-2导弹演进至重型猎鹰等商业航天巅峰", "generated_at": "2026-04-06T09:31:46.420027", "extra_fields": {"视觉元素": "历史时间轴，包含火药箭、戈达德火箭和SpaceX火箭。", "视觉焦点": "历史演进的时间轴线。", "排版布局": "水平时间轴分布，每段历史配简要文字。", "演讲者备注": "从古中国的黑火药到现代液氧甲烷发动机，火箭技术经历了千年的跨越。"}}', '25baf07b-ed71-48c9-8515-d4d7158ac7c5/pages/fa2c3f73-20f5-4a6b-80df-0c47cc3c6d75_v1.png', 'COMPLETED', '2026-04-06 09:31:28.461607', '2026-04-10 03:02:17.930327', '25baf07b-ed71-48c9-8515-d4d7158ac7c5/pages/fa2c3f73-20f5-4a6b-80df-0c47cc3c6d75_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('30e8105b-15e7-4cac-8dab-334ba1c8f165', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 3, '第 2 部分：基本物理原理', '{"title": "牛顿第三定律", "points": ["作用力与反作用力：喷射工质产生反向推力", "动量守恒定律：系统总动量保持不变", "推力公式：F = ṁ * Ve + (Pe - Pa) * Ae"]}', '{"text": "页面文字：\n### 牛顿第三定律：推力的来源\n*   **作用力与反作用力**：向下高速喷射工质，产生向上的反向推力\n*   **动量守恒定律**：工质动量增加导致火箭动量等值反向增加\n*   **推力公式**：\n    $$F = \\dot{m} \\cdot V_e + (P_e - P_a) \\cdot A_e$$", "generated_at": "2026-04-06T09:31:47.829606", "extra_fields": {"视觉元素": "滑冰者推墙或气球放气的物理原理示意图。", "视觉焦点": "推力计算公式。", "排版布局": "顶部标题，中间原理图，底部重点展示公式。", "演讲者备注": "火箭并非“蹬着空气”飞行，而是通过向后抛射物质，利用反作用力前进。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-06 09:31:28.461607', '2026-04-06 09:31:47.829606', NULL);
INSERT INTO "pages" VALUES ('cb3521d9-396a-436a-a696-9a0e9b866374', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 4, '第 2 部分：基本物理原理', '{"title": "能量转换过程", "points": ["燃烧过程：化学能转化为热能（高温高压气体）", "膨胀过程：热能在喷管中转化为动能", "喷管效应：实现气体从亚音速到超音速的跨越"]}', '{"text": "页面文字：\n### 能量转换过程\n*   **燃烧过程**：燃料与氧化剂在室内剧烈反应，化学能转为热能\n*   **膨胀过程**：高温高压气体在喷管中膨胀，热能转化为动能\n*   **喷管效应**：通过特殊的几何结构，实现气流从亚音速到超音速", "generated_at": "2026-04-06T09:31:48.344117", "extra_fields": {"视觉元素": "能量转换流程图（化学能 → 热能 → 动能）。", "视觉焦点": "能量形态的转变节点。", "排版布局": "线性流程图，配以渐变色块代表不同能量状态。", "演讲者备注": "发动机的核心任务就是高效地将燃料里的化学能转化成气体的动能。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-06 09:31:28.461607', '2026-04-06 09:31:48.344117', NULL);
INSERT INTO "pages" VALUES ('72b24608-c262-40b8-8dce-563acc48fa60', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 5, '第 3 部分：核心结构与组件', '{"title": "燃烧室 (Combustion Chamber)", "points": ["推进剂的混合与点火", "承受高温高压的材料要求", "冷却系统：再生冷却与膜冷却"]}', '{"text": "页面文字：\n### 燃烧室 (Combustion Chamber)\n*   **混合点火**：推进剂通过喷嘴精准混合并由点火装置引燃\n*   **极端环境**：需承受数千度高温及数十倍大气压力\n*   **冷却技术**：利用低温推进剂循环流动的再生冷却或膜冷却", "generated_at": "2026-04-06T09:31:49.379112", "extra_fields": {"视觉元素": "燃烧室剖面图，显示喷嘴和冷却通道。", "视觉焦点": "燃烧室内部的剧烈火焰与外壁冷却结构。", "排版布局": "大图衬底，文字环绕在相关组件周围。", "演讲者备注": "燃烧室是发动机的心脏，必须在极高温度下保持结构完整，不被烧毁。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-06 09:31:28.461607', '2026-04-06 09:31:49.379633', NULL);
INSERT INTO "pages" VALUES ('787963ca-4b7e-4698-83d4-e4fe54944b89', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 6, '第 3 部分：核心结构与组件', '{"title": "拉瓦尔喷管 (De Laval Nozzle)", "points": ["收缩段：加速亚音速气流", "喉部：气流达到音速", "扩张段：将气流加速至超音速并产生推力"]}', '{"text": "页面文字：\n### 拉瓦尔喷管 (De Laval Nozzle)\n*   **收缩段**：横截面积逐渐减小，将亚音速气流初步加速\n*   **喉部**：管径最窄处，气流流速达到临界音速状态\n*   **扩张段**：截面积增大，利用压力差将气流加速至超音速", "generated_at": "2026-04-06T09:31:50.352348", "extra_fields": {"视觉元素": "经典的沙漏型喷管示意图，标注三段区域。", "视觉焦点": "喉部位置及其物理特性。", "排版布局": "左右结构，左侧为结构图，右侧对应三个部分的解释。", "演讲者备注": "拉瓦尔喷管的巧妙之处在于，通过先收缩后扩张的形状，突破了音速限制。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-06 09:31:28.461607', '2026-04-06 09:31:50.352348', NULL);
INSERT INTO "pages" VALUES ('bbaf39c3-5d5a-4531-8097-c1ec53cb7e79', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 7, '第 3 部分：核心结构与组件', '{"title": "推进剂供应系统", "points": ["挤压式供应：利用高压气体压出推进剂", "泵压式供应：通过涡轮泵高速输送燃料", "阀门与调节机构：精确控制流量"]}', '{"text": "页面文字：\n### 推进剂供应系统\n*   **挤压式供应**：利用高压气瓶将推进剂直接压入燃烧室\n*   **泵压式供应**：通过高速涡轮泵将大量燃料强力输送\n*   **流量调节**：利用精密阀门精确控制燃料配比与发动机工况", "generated_at": "2026-04-06T09:31:51.518901", "extra_fields": {"视觉元素": "涡轮泵系统结构简化图。", "视觉焦点": "涡轮泵的旋转动力来源与传输路径。", "排版布局": "对比式排版，展示挤压式与泵压式的结构差异。", "演讲者备注": "对于大型火箭，涡轮泵就像一台动力惊人的“抽水机”，每秒输送数吨燃料。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-06 09:31:28.461607', '2026-04-06 09:31:51.518901', NULL);
INSERT INTO "pages" VALUES ('922bb3f8-2527-4962-a199-9775f85de428', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 8, '第 4 部分：分类与比较', '{"title": "液体火箭发动机", "points": ["优点：可调节推力、可多次启动、比冲高", "典型组合：液氢液氧、煤油液氧", "应用：载人航天与大型运载火箭"]}', '{"text": "页面文字：\n### 液体火箭发动机\n*   **核心优点**：推力可精准调节、可多次点火、比冲性能优异\n*   **常见组合**：液氢液氧（高效）、液氧煤油（高推力）\n*   **应用领域**：目前绝大多数大型运载火箭及载人航天任务", "generated_at": "2026-04-06T09:31:52.758794", "extra_fields": {"视觉元素": "SpaceX猛禽发动机或航天飞机主发动机照片。", "视觉焦点": "复杂的管路系统与明亮的尾焰。", "排版布局": "左侧列出性能清单，右侧展示实物图片。", "演讲者备注": "液体发动机虽然结构复杂，但其灵活性和高性能使其成为航天的主力。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-06 09:31:28.461607', '2026-04-06 09:31:52.758794', NULL);
INSERT INTO "pages" VALUES ('f22e001d-7995-4d6f-a370-4b427e457529', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 9, '第 4 部分：分类与比较', '{"title": "固体火箭发动机", "points": ["优点：结构简单、易于长期储存、可靠性高", "缺点：一旦点燃难以关机、推力难以精确调节", "应用：助推器与战术导弹"]}', '{"text": "页面文字：\n### 固体火箭发动机\n*   **核心优点**：结构简单、维护容易、可长期储存、可靠性极高\n*   **核心缺点**：一旦点火极难中途关机、推力大小难以动态调节\n*   **应用领域**：航天助推器（如长征十一号）及各类导弹系统", "generated_at": "2026-04-06T09:31:53.162493", "extra_fields": {"视觉元素": "固体燃料装药构型图（星型槽等）。", "视觉焦点": "固体燃料的药柱横截面。", "排版布局": "简洁的大图背景，文字点缀在侧边。", "演讲者备注": "固体火箭就像一个巨大的鞭炮，点火即全速运行，常用于起飞阶段的助推。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-06 09:31:28.461607', '2026-04-06 09:31:53.162493', NULL);
INSERT INTO "pages" VALUES ('f2572099-5d55-4f1b-956b-005ff80c8fcd', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 10, '第 4 部分：分类与比较', '{"title": "混合动力及新型动力", "points": ["混合火箭发动机：固态燃料+液态氧化剂", "电推进（离子发动机）：极高比冲，适用于深空探测", "核热火箭：未来远征火星的潜在动力"]}', '{"text": "页面文字：\n### 混合动力及新型动力\n*   **混合发动机**：固态燃料配合液态氧化剂，兼具安全与可控性\n*   **电推进系统**：离子发动机具有极高比冲，适用于长周期深空探测\n*   **核热火箭**：利用核能加热工质，是未来载人火星任务的潜在动力", "generated_at": "2026-04-06T09:31:54.120762", "extra_fields": {"视觉元素": "离子发动机的蓝色幽光束效果图。", "视觉焦点": "电推进系统的发光区域。", "排版布局": "三栏并列式设计，每栏代表一种新型动力。", "演讲者备注": "除了传统化学动力，电推进和核动力将带我们去向更遥远的深空。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-06 09:31:28.461607', '2026-04-06 09:31:54.120762', NULL);
INSERT INTO "pages" VALUES ('2c3054c1-7851-4a26-b03a-802a7767a489', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 11, '第 5 部分：性能指标与未来展望', '{"title": "关键性能参数", "points": ["推力 (Thrust)：衡量载重能力", "比冲 (Specific Impulse)：衡量燃料利用效率", "推重比 (Thrust-to-Weight Ratio)：衡量发动机自重效率"]}', '{"text": "页面文字：\n### 关键性能参数\n*   **推力 (Thrust)**：衡量发动机能带起多重的物体，单位为牛顿\n*   **比冲 ($I_{sp}$)**：衡量推进剂利用效率，类似汽车的“百公里油耗”\n*   **推重比**：发动机产生的推力与其自身重量之比，衡量自重效率", "generated_at": "2026-04-06T09:31:55.103870", "extra_fields": {"视觉元素": "不同发动机参数对比柱状图。", "视觉焦点": "比冲与推力的权衡关系。", "排版布局": "卡片式排版，每个参数占据一个卡片并配以简图。", "演讲者备注": "评价一台发动机好不好，推力大不大和省不省燃料是最关键的指标。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-06 09:31:28.461607', '2026-04-06 09:31:55.103870', NULL);
INSERT INTO "pages" VALUES ('bfc2c17b-dc31-40a0-9fdc-585d0a3f648c', '25baf07b-ed71-48c9-8515-d4d7158ac7c5', 12, '第 5 部分：性能指标与未来展望', '{"title": "总结与未来展望", "points": ["航天技术的可重复使用化", "环保型推进剂的发展", "迈向星际移民的动力挑战"]}', '{"text": "页面文字：\n### 总结与未来展望\n*   **可重复使用**：大幅降低发射成本，推动商业航天爆发式增长\n*   **环保化发展**：推广液氧甲烷等清洁推进剂，减少大气污染\n*   **星际征途**：更强劲、更持久的动力系统将支持人类移民火星", "generated_at": "2026-04-06T09:31:56.284181", "extra_fields": {"视觉元素": "火箭回收降落或火星基地想象图。", "视觉焦点": "可重复使用火箭垂直着陆的画面。", "排版布局": "全屏美图背景，文字居中偏下透明处理。", "演讲者备注": "动力技术的每一次突破，都在拓宽人类文明的疆域。让我们共同期待星际时代的到来。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-06 09:31:28.461607', '2026-04-06 09:31:56.284181', NULL);
INSERT INTO "pages" VALUES ('7b47bc83-8e23-4fbf-8905-e2a6e69e5483', 'd7462e9b-550b-41fb-aace-82757f7f605b', 0, NULL, '{"title": "汽车工艺的生产过程", "points": ["副标题：从板材到整车的制造全流程解析", "汇报人：[佳佳大人]"]}', '{"text": "页面文字：\n# 汽车工艺的生产过程\n## 从板材到整车的制造全流程解析\n汇报人：[佳佳大人]", "generated_at": "2026-04-10T02:32:05.710835", "extra_fields": {"视觉元素": "使用简洁的大字报风格，背景采用极简深色或纯白，突出标题的厚重感。", "视觉焦点": "页面中央的标题文字。", "排版布局": "居中对齐，留白充足，不添加任何多余装饰。", "演讲者备注": "大家好，今天由我来为大家详细解析汽车制造的全流程工艺，从最基础的板材到最终交付的整车。"}}', 'd7462e9b-550b-41fb-aace-82757f7f605b/pages/7b47bc83-8e23-4fbf-8905-e2a6e69e5483_v1.png', 'COMPLETED', '2026-04-10 02:29:41.555070', '2026-04-10 03:01:12.656208', 'd7462e9b-550b-41fb-aace-82757f7f605b/pages/7b47bc83-8e23-4fbf-8905-e2a6e69e5483_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('8a0535bf-4b2c-49f1-b01e-0f0802521969', 'd7462e9b-550b-41fb-aace-82757f7f605b', 1, 'Part 1: 汽车制造概述', '{"title": "汽车生产的四大核心工艺", "points": ["冲压（Stamping）、焊装（Welding）", "涂装（Painting）、总装（Assembly）"]}', '{"text": "页面文字：\n### 汽车生产的四大核心工艺\n*   **冲压（Stamping）：** 制造汽车的骨骼零件，确立初步轮廓。\n*   **焊装（Welding）：** 将零件焊接成型，构建白车身。\n*   **涂装（Painting）：** 赋予车身防腐性能与亮丽的色彩。\n*   **总装（Assembly）：** 完成数千个零部件的集成与整车组装。", "generated_at": "2026-04-10T02:32:06.828978", "extra_fields": {"视觉元素": "使用四个互联的图标或方块，分别代表冲压、焊装、涂装和总装。", "视觉焦点": "四大工艺的名称及其逻辑顺序。", "排版布局": "水平四等分布局，流程感强。", "演讲者备注": "汽车制造主要分为四大环节，也就是我们常说的冲压、焊装、涂装和总装，它们共同构成了现代汽车生产的主线。"}}', 'd7462e9b-550b-41fb-aace-82757f7f605b/pages/8a0535bf-4b2c-49f1-b01e-0f0802521969_v1.png', 'COMPLETED', '2026-04-10 02:29:41.555070', '2026-04-10 03:22:49.846235', 'd7462e9b-550b-41fb-aace-82757f7f605b/pages/8a0535bf-4b2c-49f1-b01e-0f0802521969_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('3d7cfd97-80d2-4bc7-b1bb-09e18c859a82', 'd7462e9b-550b-41fb-aace-82757f7f605b', 2, 'Part 1: 汽车制造概述', '{"title": "现代化工厂的特征", "points": ["高度自动化的机器人流水线", "精益生产（TPS）与数字化管理", "严苛的质量管控体系"]}', '{"text": "页面文字：\n### 现代化工厂的特征\n*   **高度自动化：** 成百上千台工业机器人实现流水线精准作业。\n*   **数字化管理：** 运用精益生产（TPS）与大数据实时监控。\n*   **严苛质控：** 建立覆盖全生命周期的标准化质量检测体系。", "generated_at": "2026-04-10T02:32:07.804117", "extra_fields": {"视觉元素": "背景可采用带有科技感的工业机器人作业线条图。", "视觉焦点": "自动化、数字化、质控三个核心词汇。", "排版布局": "左侧文字要点，右侧配合简洁的科技元素背景。", "演讲者备注": "现代化的汽车工厂不仅是机器人的舞台，更是数字化与精益管理结合的典范，确保了高效与高质量。"}}', 'd7462e9b-550b-41fb-aace-82757f7f605b/pages/3d7cfd97-80d2-4bc7-b1bb-09e18c859a82_v1.png', 'COMPLETED', '2026-04-10 02:29:41.555070', '2026-04-10 03:05:25.043391', 'd7462e9b-550b-41fb-aace-82757f7f605b/pages/3d7cfd97-80d2-4bc7-b1bb-09e18c859a82_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('09e8cbe2-127a-429a-a306-4a02586a6381', 'd7462e9b-550b-41fb-aace-82757f7f605b', 3, 'Part 2: 冲压工艺——塑造雏形', '{"title": "冲压工艺简介", "points": ["将金属板材通过模具加工成车身零件", "冲压件的精度直接影响整车品质"]}', '{"text": "页面文字：\n### 冲压工艺——塑造雏形\n*   **加工原理：** 利用大型压力机与模具将金属板材塑造成型。\n*   **品质关键：** 冲压件的尺寸精度直接决定了后续车身的配合间隙。\n*   **零件特征：** 赋予汽车流线型的外观和必要的结构强度。", "generated_at": "2026-04-10T02:32:08.808880", "extra_fields": {"视觉元素": "展示冲压模具或板材成型的示意图。", "视觉焦点": "冲压件的精度。", "排版布局": "标题居上，下方分列三项核心内容。", "演讲者备注": "冲压是汽车制造的第一步，就像制作饼干的模具一样，它赋予了汽车最初的形状和结构。"}}', 'd7462e9b-550b-41fb-aace-82757f7f605b/pages/09e8cbe2-127a-429a-a306-4a02586a6381_v1.png', 'COMPLETED', '2026-04-10 02:29:41.556070', '2026-04-10 03:00:51.887340', 'd7462e9b-550b-41fb-aace-82757f7f605b/pages/09e8cbe2-127a-429a-a306-4a02586a6381_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('c77a9bfc-2214-40f7-b12f-2d54445bbc7b', 'd7462e9b-550b-41fb-aace-82757f7f605b', 4, 'Part 2: 冲压工艺——塑造雏形', '{"title": "冲压车间的主要流程", "points": ["钢卷拆垛与清洗油膜", "冲压成型（拉延、切边、冲孔、整形）", "零件检验与入库自动化"]}', '{"text": "页面文字：\n### 冲压车间的主要流程\n1.  **拆垛与清洗：** 钢卷自动拆解并清除表面油膜与杂质。\n2.  **冲压成型：** 经历拉延、切边、冲孔、整形四道关键工序。\n3.  **自动化检验：** 零件经机器人自动检测并分拣入库。", "generated_at": "2026-04-10T02:32:09.835942", "extra_fields": {"视觉元素": "使用横向流程图展示：钢卷 -> 冲压机床 -> 检验入库。", "视觉焦点": "四道核心成型工序。", "排版布局": "线性的流程化布局。", "演讲者备注": "从钢卷进场到零件入库，整个过程高度自动化，尤其是拉延工艺，是决定零件品质的核心。"}}', NULL, 'FAILED', '2026-04-10 02:29:41.556070', '2026-04-10 03:26:43.799918', NULL);
INSERT INTO "pages" VALUES ('2701180f-3a6a-4f00-b8bc-6c6f6d59076b', 'd7462e9b-550b-41fb-aace-82757f7f605b', 5, 'Part 3: 焊装工艺——构建骨架', '{"title": "白车身（BIW）的形成", "points": ["将各种冲压件通过焊接组合成完整车身", "关键点：强度、刚度与维度精度"]}', '{"text": "页面文字：\n### 焊装工艺——构建骨架\n*   **白车身（BIW）：** 各种冲压零件通过焊接形成的金属框架。\n*   **技术要求：** 必须具备极高的焊接强度、车身刚度与维度精度。\n*   **核心功能：** 为整车提供支撑力，是保障乘客安全的第一道防线。", "generated_at": "2026-04-10T02:32:10.806337", "extra_fields": {"视觉元素": "展示白车身（无内饰、无漆）的结构透视图。", "视觉焦点": "白车身的强度与精度。", "排版布局": "左侧展示车身结构图，右侧排列文字说明。", "演讲者备注": "焊装工艺将零散的冲压件合为一体，形成“白车身”，这是整台车的骨架。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 02:29:41.556070', '2026-04-10 02:32:10.806337', NULL);
INSERT INTO "pages" VALUES ('41d284d6-ba27-46ae-be3a-b72ac133fa44', 'd7462e9b-550b-41fb-aace-82757f7f605b', 6, 'Part 3: 焊装工艺——构建骨架', '{"title": "核心焊接技术", "points": ["工业机器人点焊与激光焊接", "自动化涂胶与螺柱焊", "视觉检测系统对精度监控"]}', '{"text": "页面文字：\n### 核心焊接技术\n*   **先进连接：** 广泛应用工业机器人点焊与高效率激光焊接。\n*   **辅助工艺：** 配合自动化涂胶、螺柱焊等多种复合连接方式。\n*   **视觉监控：** 采用视觉检测系统对每个焊点进行实时精度监控。", "generated_at": "2026-04-10T02:32:11.792805", "extra_fields": {"视觉元素": "机器人挥舞焊枪进行作业的剪影或图标。", "视觉焦点": "机器人点焊与激光焊。", "排版布局": "三栏式排版，每栏上方配以对应的微型图标。", "演讲者备注": "现代焊装车间基本实现了100%自动化，激光焊接的应用极大地提升了车身连接的紧密性。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 02:29:41.556070', '2026-04-10 02:32:11.792805', NULL);
INSERT INTO "pages" VALUES ('cbe4ef44-c4eb-423b-bbdd-b53480dad1d7', 'd7462e9b-550b-41fb-aace-82757f7f605b', 7, 'Part 4: 涂装工艺——美化与防护', '{"title": "涂装的主要功能", "points": ["防腐蚀保护（核心功能）", "装饰性与色彩呈现", "密封与隔音处理"]}', '{"text": "页面文字：\n### 涂装工艺——美化与防护\n*   **核心功能：** 提供卓越的防腐蚀保护，延长车身使用寿命。\n*   **装饰美化：** 呈现丰富的色彩效果，提升整车的感官品质。\n*   **功能延伸：** 进行车身密封、隔音处理及抗石击防护。", "generated_at": "2026-04-10T02:32:12.687745", "extra_fields": {"视觉元素": "多层次的漆膜结构示意图（底漆、中涂、面漆）。", "视觉焦点": "防腐蚀与色彩。", "排版布局": "采用对比色块区分功能描述。", "演讲者备注": "涂装不仅是为了好看，更重要的是防锈。通过电泳和多层喷涂，保护车身不受环境侵蚀。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 02:29:41.556070', '2026-04-10 02:32:12.687745', NULL);
INSERT INTO "pages" VALUES ('3a5a0a06-f2bd-43ce-86eb-c6e607ec0d6a', 'd7462e9b-550b-41fb-aace-82757f7f605b', 8, 'Part 4: 涂装工艺——美化与防护', '{"title": "涂装生产线流程", "points": ["前处理与电泳（形成防锈底层）", "密封涂胶与PVC喷涂", "中涂、面漆与清漆喷涂及烘干"]}', '{"text": "页面文字：\n### 涂装生产线流程\n*   **前处理与电泳：** 彻底清洗并形成第一层致密的防锈底漆。\n*   **密封与PVC喷涂：** 对焊缝进行密封并喷涂抗石击保护涂层。\n*   **面漆喷涂：** 完成中涂、面漆、清漆喷涂及高温烘干固化。", "generated_at": "2026-04-10T02:32:13.700228", "extra_fields": {"视觉元素": "阶梯状流程图，模拟涂装池与喷漆室。", "视觉焦点": "电泳与面漆喷涂环节。", "排版布局": "垂直递进式布局。", "演讲者备注": "涂装环境对洁净度要求极高，尤其是电泳工艺，是保证汽车几年甚至十几年不生锈的关键。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 02:29:41.556070', '2026-04-10 02:32:13.701227', NULL);
INSERT INTO "pages" VALUES ('196a16b6-9812-46f3-ad05-3cd78aec372c', 'd7462e9b-550b-41fb-aace-82757f7f605b', 9, 'Part 5: 总装工艺——整车集成', '{"title": "总装车间的功能", "points": ["将数千个零部件组装到涂装后的车身上", "汽车制造中最复杂、人工最密集的环节"]}', '{"text": "页面文字：\n### 总装工艺——整车集成\n*   **复杂集成：** 将数千个零部件精准组装到涂装后的车身上。\n*   **环节特性：** 汽车制造中工序最繁多、人工密度最高的环节。\n*   **作业核心：** 讲究装配逻辑与防错管理，确保整车功能完整。", "generated_at": "2026-04-10T02:32:14.831376", "extra_fields": {"视觉元素": "错落有致的零部件与车身合影的示意图。", "视觉焦点": "整车集成与复杂性。", "排版布局": "大标题下分列三个重要观点，下方留出大幅空间展示总装全貌感。", "演讲者备注": "总装是赋予汽车灵魂的过程。在这里，车身、发动机、内饰才真正结合成一台可以开动的车。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 02:29:41.556070', '2026-04-10 02:32:14.831376', NULL);
INSERT INTO "pages" VALUES ('60084ef0-31e9-476d-9d97-bb60eaccc400', 'd7462e9b-550b-41fb-aace-82757f7f605b', 10, 'Part 5: 总装工艺——整车集成', '{"title": "总装关键步骤", "points": ["内饰装配（仪表板、座椅、地毯）", "底盘合装（发动机、变速箱、悬架集成）", "外饰件与车轮安装"]}', '{"text": "页面文字：\n### 总装关键步骤\n1.  **内饰装配：** 安装仪表板、座椅、地毯及全车线束。\n2.  **底盘合装：** 动力总成（发动机、变速箱）与悬架整体合装。\n3.  **外饰安装：** 安装挡风玻璃、前后灯组及四轮轮胎。", "generated_at": "2026-04-10T02:32:15.849611", "extra_fields": {"视觉元素": "使用三步式的结构图，展示从空壳车身到成品的变化。", "视觉焦点": "底盘合装（大合装）。", "排版布局": "1-2-3数字标序号排版，清晰有序。", "演讲者备注": "底盘合装是总装的核心，业界称为“Marriage”，象征着动力系统与车身的完美结合。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 02:29:41.556070', '2026-04-10 02:32:15.849611', NULL);
INSERT INTO "pages" VALUES ('ff6602e4-71fe-4550-8b92-5cb53ad70221', 'd7462e9b-550b-41fb-aace-82757f7f605b', 11, 'Part 6: 检测与成品交付', '{"title": "严苛的质量检测", "points": ["四轮定位与大灯检测", "淋雨测试（密封性检验）", "综合路试与电器功能诊断"]}', '{"text": "页面文字：\n### 严苛的质量检测\n*   **静态检测：** 四轮定位精准调校、大灯照射角度自动检测。\n*   **密封测试：** 模拟极端天气的超高压淋雨测试，检验密封性。\n*   **综合路试：** 涵盖多种路况的实车驾驶，诊断整车电器功能。", "generated_at": "2026-04-10T02:32:17.153714", "extra_fields": {"视觉元素": "检测线上的强光或喷淋测试图标。", "视觉焦点": "淋雨测试与功能诊断。", "排版布局": "三项要点呈并列排布，每项配以“OK”质检通过的视觉符号。", "演讲者备注": "每一台下线的汽车都要经过“魔鬼训练”般的测试，只有通过所有关卡，才能算合格。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 02:29:41.556070', '2026-04-10 02:32:17.153714', NULL);
INSERT INTO "pages" VALUES ('fd8f0bad-60c7-4170-8dd8-e652c2830353', 'd7462e9b-550b-41fb-aace-82757f7f605b', 12, 'Part 6: 检测与成品交付', '{"title": "完工与发运", "points": ["成品车入库管理", "PDI（交车前检查）流程", "迈向市场的最后一步"]}', '{"text": "页面文字：\n### 完工与发运\n*   **成品入库：** 成品车通过入库检查，进入智能化物流中心。\n*   **PDI检查：** 最终交付前进行标准化的质量确认与细节清洁。\n*   **迈向市场：** 完成制造全旅程，准备运往全国各地经销商。", "generated_at": "2026-04-10T02:32:18.234114", "extra_fields": {"视觉元素": "一排排整齐待发的汽车背景，或物流货运车的剪影。", "视觉焦点": "PDI流程与发运。", "排版布局": "简洁的终点式布局，呼应第一页。", "演讲者备注": "最后，经过PDI检查的车辆将发往市场。以上就是汽车从一块钢板变成整车的全部精妙过程。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 02:29:41.556070', '2026-04-10 02:32:18.234114', NULL);
INSERT INTO "pages" VALUES ('a99d9b79-5cb2-46b3-abdf-8c18a9e6dc5a', '9c66b6da-ffe0-4bf2-b22c-40423b59347b', 0, '第一部分：教育的核心理念', '{"title": "作为家长，如何教育培养下一代", "points": ["副标题：陪伴孩子共同成长，成就未来之才", "汇报人：[您的姓名]"]}', '{"text": "页面文字：\n# 作为家长，如何教育培养下一代\n## 陪伴孩子共同成长，成就未来之才\n汇报人：[您的姓名]", "generated_at": "2026-04-10T03:18:36.434796", "extra_fields": {"视觉元素": "简约大气的设计风格，以温暖的色调为底。", "视觉焦点": "中心大标题“作为家长，如何教育培养下一代”。", "排版布局": "标题居中对齐，副标题位于标题下方，汇报人姓名位于页面底部。", "演讲者备注": "开篇寄语，强调家庭教育在孩子成长过程中的基石作用。"}}', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/a99d9b79-5cb2-46b3-abdf-8c18a9e6dc5a_v1.png', 'COMPLETED', '2026-04-10 03:17:39.523434', '2026-04-10 05:03:54.235287', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/a99d9b79-5cb2-46b3-abdf-8c18a9e6dc5a_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('155fb5be-7fed-453f-a227-000e9d7e8e80', '9c66b6da-ffe0-4bf2-b22c-40423b59347b', 1, '第一部分：教育的核心理念', '{"title": "教育的本质：唤醒与引导", "points": ["从“控制者”转向“领航员”", "尊重孩子的个体差异与天性", "培养独立人格而非复刻他人"]}', '{"text": "页面文字：\n### 第一部分：教育的核心理念\n## 教育的本质：唤醒与引导\n*   **身份转变：** 从居高临下的“控制者”转向人生路上的“领航员”。\n*   **尊重差异：** 尊重孩子独特的个体天性，拒绝千篇一律的模板化教育。\n*   **独立人格：** 核心目标是培养拥有独立思考能力的人，而非他人的复刻版。", "generated_at": "2026-04-10T03:18:37.500266", "extra_fields": {"视觉元素": "使用帆船航向灯塔的剪影或抽象图标表达“领航”概念。", "视觉焦点": "标题“教育的本质”及“唤醒与引导”关键词。", "排版布局": "左右结构，左侧展示核心理念文字，右侧放置相关意象图标。", "演讲者备注": "解释教育不是灌输，而是点燃火种，家长应学会放手并提供方向。"}}', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/155fb5be-7fed-453f-a227-000e9d7e8e80_v1.png', 'COMPLETED', '2026-04-10 03:17:39.523434', '2026-04-10 04:07:02.328436', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/155fb5be-7fed-453f-a227-000e9d7e8e80_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('b794d4a8-4156-4a08-a1f6-29dd240573d2', '9c66b6da-ffe0-4bf2-b22c-40423b59347b', 2, '第二部分：关键素质的培养', '{"title": "价值观与品德塑造", "points": ["树立诚实、正直与责任感", "培养同理心与感恩之心", "通过社会实践增强公民意识"]}', '{"text": "页面文字：\n### 第二部分：关键素质的培养\n## 价值观与品德塑造\n*   **道德基石：** 在日常点滴中树立诚实、正直与高度的社会责任感。\n*   **情感连接：** 培养同理心与感恩之心，学会换位思考并珍惜他人付出。\n*   **公民意识：** 积极参与社会实践活动，增强社会归属感与公共意识。", "generated_at": "2026-04-10T03:18:38.412285", "extra_fields": {"视觉元素": "三棵正在成长的小树，分别代表诚实、同理心、责任感。", "视觉焦点": "三个并列的素质培养要点。", "排版布局": "横向三个卡片式布局，每个卡片对应一个核心素质。", "演讲者备注": "品德是孩子的立身之本，优秀的价值观比优异的成绩更重要。"}}', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/b794d4a8-4156-4a08-a1f6-29dd240573d2_v1.png', 'COMPLETED', '2026-04-10 03:17:39.523434', '2026-04-10 04:07:23.368000', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/b794d4a8-4156-4a08-a1f6-29dd240573d2_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('d152e043-64c6-4884-991f-951e7ee03fbe', '9c66b6da-ffe0-4bf2-b22c-40423b59347b', 3, '第二部分：关键素质的培养', '{"title": "学习动力与终身学习习惯", "points": ["激发好奇心，保护探索欲望", "培养良好的阅读习惯与独立思考能力", "正确看待挫折，提升抗逆力（挫折教育）"]}', '{"text": "页面文字：\n### 第二部分：关键素质的培养\n## 学习动力与终身学习习惯\n*   **守护好奇：** 积极回应孩子的提问，保护其对未知世界的探索欲望。\n*   **思维深度：** 建立亲子共读习惯，培养逻辑分析与独立思考能力。\n*   **抗逆力培养：** 正确看待失败与挫折，在磨砺中提升心理弹性和复原力。", "generated_at": "2026-04-10T03:18:39.619962", "extra_fields": {"视觉元素": "书籍与飞翔的纸飞机，象征知识赋予翅膀。", "视觉焦点": "好奇心、思考力、抗逆力三个关键词。", "排版布局": "采用阶梯式排版，寓意学习与成长的进阶过程。", "演讲者备注": "授人以鱼不如授人以渔，习惯和心态是支撑终身发展的动力。"}}', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/d152e043-64c6-4884-991f-951e7ee03fbe_v1.png', 'COMPLETED', '2026-04-10 03:17:39.523434', '2026-04-10 04:11:33.082230', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/d152e043-64c6-4884-991f-951e7ee03fbe_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('3f177c39-9849-4fc6-8ac2-e1554af3d68f', '9c66b6da-ffe0-4bf2-b22c-40423b59347b', 4, '第二部分：关键素质的培养', '{"title": "生活技能与自我管理", "points": ["培养时间管理与计划能力", "劳动教育：自理能力与家务参与", "财商启蒙：正确的金钱观与消费观"]}', '{"text": "页面文字：\n### 第二部分：关键素质的培养\n## 生活技能与自我管理\n*   **掌控时间：** 引导孩子制定学习与休息计划，培养自律的时间意识。\n*   **劳动教育：** 鼓励参与家务劳动，在实践中提升生活自理能力。\n*   **财商启蒙：** 通过管理零用钱，建立正确的金钱观念与理性消费习惯。", "generated_at": "2026-04-10T03:18:40.493612", "extra_fields": {"视觉元素": "包含时钟、围裙、钱币的图标组合，对应三项生活技能。", "视觉焦点": "自我管理能力与生活实践的结合点。", "排版布局": "三分式纵向排列，图文对照，清晰直观。", "演讲者备注": "生活技能是独立的开始，让孩子在真实的琐事中学会负责。"}}', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/3f177c39-9849-4fc6-8ac2-e1554af3d68f_v1.png', 'COMPLETED', '2026-04-10 03:17:39.523434', '2026-04-10 03:24:54.841550', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/3f177c39-9849-4fc6-8ac2-e1554af3d68f_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('5c67c687-6d91-4b8e-96b3-458df41d8c08', '9c66b6da-ffe0-4bf2-b22c-40423b59347b', 5, '第三部分：高效的亲子沟通', '{"title": "建立信任的沟通桥梁", "points": ["倾听的艺术：听懂孩子背后的情绪", "拒绝说教，采用平等交流模式", "定期举行家庭会议，增强参与感"]}', '{"text": "页面文字：\n### 第三部分：高效的亲子沟通\n## 建立信任的沟通桥梁\n*   **倾听艺术：** 蹲下来用心聆听，觉察并接纳孩子言语背后的真实情绪。\n*   **平等模式：** 拒绝单向的说教与命令，建立双向互动的民主交流机制。\n*   **家庭会议：** 定期讨论家庭事务，给予孩子话语权，增强家庭成员感。", "generated_at": "2026-04-10T03:18:41.521622", "extra_fields": {"视觉元素": "两个交叠的对话框或相互拉手的小人。", "视觉焦点": "强调“平等的交流模式”。", "排版布局": "环形布局，中心为“沟通桥梁”，四周发散出三个要点。", "演讲者备注": "沟通的关键在于听，而非说；建立信任是所有教育的前提。"}}', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/5c67c687-6d91-4b8e-96b3-458df41d8c08_v1.png', 'COMPLETED', '2026-04-10 03:17:39.523434', '2026-04-10 03:22:48.576972', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/5c67c687-6d91-4b8e-96b3-458df41d8c08_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('57450825-8096-484c-8867-be655b9973d8', '9c66b6da-ffe0-4bf2-b22c-40423b59347b', 6, '第三部分：高效的亲子沟通', '{"title": "科学的奖惩与边界感", "points": ["设立清晰的家庭规则", "奖惩并举：正面激励的力量", "尊重孩子的隐私与个人空间"]}', '{"text": "页面文字：\n### 第三部分：高效的亲子沟通\n## 科学的奖惩与边界感\n*   **规则意识：** 共同商定清晰的家庭行为准则，确保赏罚有据可依。\n*   **正面激励：** 侧重过程和努力的肯定，用积极的反馈激发内在驱动力。\n*   **尊重隐私：** 给孩子留出个人心理空间，在边界内给予充分的自主权。", "generated_at": "2026-04-10T03:18:42.390652", "extra_fields": {"视觉元素": "标尺与握手的图标，代表规则与契约精神。", "视觉焦点": "奖惩并举与边界感的平衡。", "排版布局": "对比式排版，左侧讲规则与奖惩，右侧讲尊重与空间。", "演讲者备注": "规则给孩子安全感，尊重给孩子尊严感。"}}', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/57450825-8096-484c-8867-be655b9973d8_v1.png', 'COMPLETED', '2026-04-10 03:17:39.523434', '2026-04-10 03:23:39.990975', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/57450825-8096-484c-8867-be655b9973d8_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('c1f07934-9c72-41ef-acf7-69297ff927f7', '9c66b6da-ffe0-4bf2-b22c-40423b59347b', 7, '第四部分：父母的自我成长', '{"title": "言传身教的力量", "points": ["父母是孩子的第一任榜样", "保持情绪稳定，营造温馨家庭氛围", "坚持自我学习，与孩子同步成长"]}', '{"text": "页面文字：\n### 第四部分：父母的自我成长\n## 言传身教的力量\n*   **第一榜样：** 父母的行为是孩子的一面镜子，身教远比言教更有影响力。\n*   **环境基调：** 保持情绪稳定与平和，为孩子营造温馨、包容的家庭氛围。\n*   **同步进化：** 坚持阅读与自我提升，向孩子展示终身学习者的姿态。", "generated_at": "2026-04-10T03:18:43.296424", "extra_fields": {"视觉元素": "大手拉小手，走在洒满阳光的路上。", "视觉焦点": "强调“父母是孩子的第一任榜样”。", "排版布局": "大图衬底，文字居中或偏一侧，留白增加意境。", "演讲者备注": "最好的教育是经营好自己，通过自己的进步带动孩子的进步。"}}', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/c1f07934-9c72-41ef-acf7-69297ff927f7_v1.png', 'COMPLETED', '2026-04-10 03:17:39.523434', '2026-04-10 03:20:52.812638', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/c1f07934-9c72-41ef-acf7-69297ff927f7_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('da3b5052-d16f-4f0b-83d2-3ba2d31e830c', '9c66b6da-ffe0-4bf2-b22c-40423b59347b', 8, '第四部分：父母的自我成长', '{"title": "总结与寄语", "points": ["接受孩子的不完美", "教育是一场马拉松，而非百米冲刺", "用爱与耐心静待花开"]}', '{"text": "页面文字：\n### 第四部分：父母的自我成长\n## 总结与寄语\n*   **接纳平凡：** 学会接纳孩子的不完美，发掘并欣赏其独特的闪光点。\n*   **长期主义：** 教育是一场漫长的马拉松，需保持定力，拒绝焦虑。\n*   **静待花开：** 用最深沉的爱与足够的耐心，陪伴孩子在时光中绽放。", "generated_at": "2026-04-10T03:18:44.189574", "extra_fields": {"视觉元素": "一朵在晨曦中缓缓绽放的花朵特写。", "视觉焦点": "结束语“用爱与耐心静待花开”。", "排版布局": "极简排版，大字体展示核心寄语，营造感人氛围。", "演讲者备注": "收尾总结，给予家长鼓励，回归教育的温情本质。"}}', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/da3b5052-d16f-4f0b-83d2-3ba2d31e830c_v1.png', 'COMPLETED', '2026-04-10 03:17:39.523434', '2026-04-10 04:11:24.888446', '9c66b6da-ffe0-4bf2-b22c-40423b59347b/pages/da3b5052-d16f-4f0b-83d2-3ba2d31e830c_v1_thumb.jpg');
INSERT INTO "pages" VALUES ('8b191bd4-a2e1-4860-b09e-5e474f17f2d8', 'f33bef5c-ce36-4f40-b4a9-b4e24cfe1720', 0, NULL, '{"title": "2025年度工作总结与2026年度规划", "points": ["副标题：回顾过去，展望未来", "汇报人：[您的姓名/部门]"]}', '{"text": "页面文字：\n# 2025年度工作总结与2026年度规划\n## 回顾过去，展望未来\n汇报人：[您的姓名/部门]", "generated_at": "2026-04-10T05:32:17.259340", "extra_fields": {"视觉元素": "极简背景，商务字体，大面积留白。", "视觉焦点": "中心标题“2025年度工作总结与2026年度规划”。", "排版布局": "居中对齐，标题居中突出，副标题与汇报信息置于下方。", "演讲者备注": "欢迎各位领导和同事，今天由我向大家汇报2025年的工作总结及明年的发展规划。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 05:15:21.713599', '2026-04-10 05:32:17.259340', NULL);
INSERT INTO "pages" VALUES ('dfa9639b-edf8-4462-b7a2-63b1c7c76786', 'f33bef5c-ce36-4f40-b4a9-b4e24cfe1720', 1, '第一部分：年度工作回顾', '{"title": "核心目标达成情况", "points": ["年度KPI指标完成度分析", "重点项目执行进度复盘", "职能工作日常开展情况"]}', '{"text": "页面文字：\n### 第一部分：年度工作回顾\n## 核心目标达成情况\n*   **KPI指标完成度：** 深度分析年度关键绩效指标，对标年度目标核算最终达成率。\n*   **重点项目复盘：** 复盘核心项目执行路径，总结项目过程中的经验与交付质量。\n*   **职能工作开展：** 汇报日常行政与职能工作开展情况，确保基础业务稳健运行。", "generated_at": "2026-04-10T05:32:18.449157", "extra_fields": {"视觉元素": "KPI达成百分比环形图，重点项目进度条。", "视觉焦点": "核心KPI达成百分比数据。", "排版布局": "左右结构，左侧展示核心指标图表，右侧列出具体分析要点。", "演讲者备注": "本页重点汇报2025年整体目标的完成情况，通过KPI数据直观展现过去一年的工作成果。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 05:15:21.713599', '2026-04-10 05:32:18.449157', NULL);
INSERT INTO "pages" VALUES ('fc83a3d6-487e-44e6-bbaf-21512ffcdda8', 'f33bef5c-ce36-4f40-b4a9-b4e24cfe1720', 2, '第一部分：年度工作回顾', '{"title": "关键里程碑", "points": ["上半年重要节点回顾", "下半年突破性进展", "跨部门协作成果"]}', '{"text": "页面文字：\n### 第一部分：年度工作回顾\n## 关键里程碑\n*   **上半年节点回顾：** 梳理1-6月重要项目启动、签约及阶段性验收成果。\n*   **下半年突破进展：** 总结7-12月业务突破点，包括市场拓展与新技术应用。\n*   **跨部门协作成果：** 记录部门间联合作战取得的阶段性胜利，展示团队协同效率。", "generated_at": "2026-04-10T05:32:19.621667", "extra_fields": {"视觉元素": "水平时间轴（S-Curve），关键节点图标。", "视觉焦点": "时间轴上的重要时间节点及其对应的重大成就。", "排版布局": "横向时间轴布局，按月份顺序由左至右排列关键事件。", "演讲者备注": "通过时间轴回顾全年的大事件，下半年的突破性进展为我们全年的增长奠定了基础。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 05:15:21.713599', '2026-04-10 05:32:19.621667', NULL);
INSERT INTO "pages" VALUES ('76b51920-f4f0-41a4-8c26-e99690163bbd', 'f33bef5c-ce36-4f40-b4a9-b4e24cfe1720', 3, '第二部分：核心业绩与亮点', '{"title": "业务增长分析", "points": ["核心数据同比与环比增长", "市场份额及竞争力提升", "成本控制与效率优化成效"]}', '{"text": "页面文字：\n### 第二部分：核心业绩与亮点\n## 业务增长分析\n*   **增长数据对比：** 展示核心业务数据同比与环比增长，量化业务规模扩张。\n*   **市场竞争力提升：** 分析市场占有率变动情况，评估品牌在行业内的竞争位次。\n*   **成本与效率优化：** 汇报成本控制措施的执行成效，展示人效与流程效率的提升。", "generated_at": "2026-04-10T05:32:21.035479", "extra_fields": {"视觉元素": "折线图（展示趋势）与柱状图（对比增长），向上增长的箭头符号。", "视觉焦点": "同比与环比增长的具体百分数。", "排版布局": "三栏式布局，分别对应数据增长、竞争力提升和效率优化。", "演讲者备注": "本节聚焦核心业绩指标，通过数据对比可以清晰看到我们在市场份额和效率上的提升。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 05:15:21.713599', '2026-04-10 05:32:21.035479', NULL);
INSERT INTO "pages" VALUES ('8e08eed0-c073-4e89-9835-79d1cbc57004', 'f33bef5c-ce36-4f40-b4a9-b4e24cfe1720', 4, '第二部分：核心业绩与亮点', '{"title": "成功案例分享", "points": ["标杆项目经验总结", "创新工作模式探索", "团队赋能与人才发展"]}', '{"text": "页面文字：\n### 第二部分：核心业绩与亮点\n## 成功案例分享\n*   **标杆项目经验：** 总结年度最成功项目的实施策略，提炼可复制的方法论。\n*   **创新模式探索：** 分享在业务模式或技术手段上的创新尝试，评估应用效果。\n*   **团队赋能发展：** 展示人才培养成果，包括内部培训、技能提升及团队士气建设。", "generated_at": "2026-04-10T05:32:21.854128", "extra_fields": {"视觉元素": "项目实景或案例插图，勋章/奖杯图标。", "视觉焦点": "标杆项目的核心成功因子。", "排版布局": "卡片式布局，突出三个不同维度的亮点展示。", "演讲者备注": "我们要通过对标杆案例的复盘，将成功的经验转化为部门可长期传承的工作模式。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 05:15:21.714598', '2026-04-10 05:32:21.854128', NULL);
INSERT INTO "pages" VALUES ('9ac37ccb-cc27-462e-bf55-d7b4af30fe1c', 'f33bef5c-ce36-4f40-b4a9-b4e24cfe1720', 5, '第三部分：问题分析与反思', '{"title": "存在的挑战", "points": ["业务流程中的薄弱环节", "资源配置与协调问题", "外部环境变化的应对不足"]}', '{"text": "页面文字：\n### 第三部分：问题分析与反思\n## 存在的挑战\n*   **业务流程薄弱点：** 反思现有操作流程中的冗余环节，识别影响效率的症结所在。\n*   **资源配置问题：** 剖析人力、物力在高峰期的调配难度，指出协作中的资源瓶颈。\n*   **外部环境应对：** 总结在面对政策变化或市场波动时，部门响应速度的不足。", "generated_at": "2026-04-10T05:32:23.270637", "extra_fields": {"视觉元素": "SWOT分析矩阵中的“劣势”部分，警告图标或深色调图形。", "视觉焦点": "当前业务流程中亟需解决的三个核心痛点。", "排版布局": "列表式布局，使用清晰的符号引导每一条挑战内容。", "演讲者备注": "在看到成绩的同时，我们也必须正视目前存在的流程及资源调配问题，这是明年改进的方向。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 05:15:21.714598', '2026-04-10 05:32:23.270637', NULL);
INSERT INTO "pages" VALUES ('d082459f-5924-4127-96d6-74325d44b9fd', 'f33bef5c-ce36-4f40-b4a9-b4e24cfe1720', 6, '第三部分：问题分析与反思', '{"title": "改进措施建议", "points": ["流程再造与制度优化", "技术手段引入与工具升级", "团队能力短板补齐方案"]}', '{"text": "页面文字：\n### 第三部分：问题分析与反思\n## 改进措施建议\n*   **流程再造与优化：** 精简审批环节，通过制度优化提升跨部门流转的响应速度。\n*   **技术引入与升级：** 引入自动化工具或管理系统，利用技术手段替代低效手工环节。\n*   **能力短板补齐：** 针对性开展专项培训，针对团队技能弱项制定人才补充计划。", "generated_at": "2026-04-10T05:32:24.476973", "extra_fields": {"视觉元素": "逻辑流程图（从现状到优化），齿轮或工具图标。", "视觉焦点": "针对性的解决方案和改进后的预期效果。", "排版布局": "左右对比布局，左侧列出问题，右侧展示对应的改进措施。", "演讲者备注": "针对前文提到的挑战，我们制定了三方面的改进措施，旨在实现技术与制度的双驱动。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 05:15:21.714598', '2026-04-10 05:32:24.476973', NULL);
INSERT INTO "pages" VALUES ('ce20249e-2f95-4687-aa2a-327bf0aabdef', 'f33bef5c-ce36-4f40-b4a9-b4e24cfe1720', 7, '第四部分：2024年度规划', '{"title": "年度战略目标", "points": ["核心业绩指标设定", "业务重点拓展方向", "品牌价值提升计划"]}', '{"text": "页面文字：\n### 第四部分：2026年度规划\n## 年度战略目标\n*   **核心业绩指标设定：** 明确2026年度总产值、用户数及核心KPI的具体目标数值。\n*   **重点业务拓展方向：** 确定新的一年将要进军的新市场或深挖的垂直领域。\n*   **品牌价值提升计划：** 制定年度品牌宣传与市场公关策略，提升行业品牌影响力。", "generated_at": "2026-04-10T05:32:25.803932", "extra_fields": {"视觉元素": "望远镜图标，目标靶心图标，大气的前瞻性背景图。", "视觉焦点": "2026年度的核心业绩KPI数值。", "排版布局": "居中对称布局，核心指标置于页面中心位置，周边环绕支撑计划。", "演讲者备注": "展望2026年，我们的核心目标是在稳固现有业务的基础上，实现核心业绩的再突破。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 05:15:21.714598', '2026-04-10 05:32:25.803932', NULL);
INSERT INTO "pages" VALUES ('73eb21eb-4a2e-4186-98af-0b1afbf31c5f', 'f33bef5c-ce36-4f40-b4a9-b4e24cfe1720', 8, '第四部分：2024年度规划', '{"title": "实施路径与计划", "points": ["季度阶段性任务拆解", "资源需求与预算编制", "风险预控与应对机制"]}', '{"text": "页面文字：\n### 第四部分：2024年度规划\n## 实施路径与计划\n*   **季度任务拆解：** 将全年战略目标细化至各季度，明确阶段性交付产物。\n*   **资源需求与预算：** 申请2026年度关键项目资源，明确预算编制与使用重点。\n*   **风险预控机制：** 建立市场预警与应急预案，提高团队应对突发变化的抵抗力。", "generated_at": "2026-04-10T05:32:26.886928", "extra_fields": {"视觉元素": "甘特图概要，资源漏斗模型，盾牌图标（风险预控）。", "视觉焦点": "第一季度的启动计划与资源分配。", "排版布局": "矩阵式布局，按时间（季度）与资源维度进行拆分展示。", "演讲者备注": "为了确保目标达成，我们将任务分解到每一个季度，并预设了严密的风险防范机制。"}}', NULL, 'DESCRIPTION_GENERATED', '2026-04-10 05:15:21.714598', '2026-04-10 05:32:26.886928', NULL);

-- ----------------------------
-- Table structure for projects
-- ----------------------------
DROP TABLE IF EXISTS "projects";
CREATE TABLE "projects" (
  "id" VARCHAR(36) NOT NULL,
  "idea_prompt" TEXT,
  "outline_text" TEXT,
  "description_text" TEXT,
  "extra_requirements" TEXT,
  "creation_type" VARCHAR(20) NOT NULL,
  "template_image_path" VARCHAR(500),
